script:
# Journal Entry (After Cancel): undo accrual / payment on the Work Allocation cost lines
if doc.get("custom_work_allocation") and doc.get("custom_wa_lines"):
    lines = json.loads(doc.custom_wa_lines)
    wa = frappe.get_doc("Work Allocation", doc.custom_work_allocation)
    for c in wa.costs:
        if c.source_key not in lines:
            continue
        amt = frappe.utils.flt(lines[c.source_key])
        if doc.custom_wa_purpose == "Accrual":
            if c.journal_entry == doc.name:
                if frappe.utils.flt(c.paid_amount) > 0.005:
                    frappe.throw(f"'{c.source}' for {c.payee_name} already has payments. Cancel those payments first.")
                c.accounting_status = "Not Posted"
                c.journal_entry = None
        else:
            newpaid = frappe.utils.flt(c.paid_amount) - amt
            c.paid_amount = newpaid if newpaid > 0 else 0
            if c.payment_reference == doc.name:
                c.payment_doctype = None
                c.payment_reference = None
                c.payment_date = None
    wa.save(ignore_permissions=True)

# Journal Entry (Before Delete): a deleted draft accrual frees its cost lines for posting again
if doc.docstatus == 0 and doc.get("custom_work_allocation") and doc.get("custom_wa_purpose") == "Accrual" and frappe.db.exists("Work Allocation", doc.custom_work_allocation):
    wa = frappe.get_doc("Work Allocation", doc.custom_work_allocation)
    changed = False
    for c in wa.costs:
        if c.journal_entry == doc.name and c.accounting_status == "Draft JE":
            c.accounting_status = "Not Posted"
            c.journal_entry = None
            changed = True
    if changed:
        wa.save(ignore_permissions=True)

# Journal Entry (After Submit): accrual -> cost lines Posted; payment JE -> paid amount
if doc.get("custom_work_allocation") and doc.get("custom_wa_lines"):
    lines = json.loads(doc.custom_wa_lines)
    wa = frappe.get_doc("Work Allocation", doc.custom_work_allocation)
    for c in wa.costs:
        if c.source_key not in lines:
            continue
        amt = frappe.utils.flt(lines[c.source_key])
        if doc.custom_wa_purpose == "Accrual":
            c.accounting_status = "Posted"
            c.journal_entry = doc.name
        else:
            if c.accounting_status != "Posted":
                frappe.throw(f"Cost line '{c.source}' for {c.payee_name} is not posted to accounts yet.")
            newpaid = frappe.utils.flt(c.paid_amount) + amt
            if newpaid > frappe.utils.flt(c.amount) + 0.01:
                frappe.throw(f"This payment would overpay '{c.source}' for {c.payee_name} (amount {c.amount}, already paid {c.paid_amount}).")
            c.paid_amount = newpaid
            c.payment_doctype = "Journal Entry"
            c.payment_reference = doc.name
            c.payment_date = doc.posting_date
    wa.save(ignore_permissions=True)

# Payment Entry (After Cancel): reverse job cost payments / customer charge receipts
if doc.get("custom_work_allocation") and doc.get("custom_wa_lines"):
    data = json.loads(doc.custom_wa_lines)
    costs = data.get("costs") or {}
    charges = data.get("charges") or []
    wa = frappe.get_doc("Work Allocation", doc.custom_work_allocation)
    for c in wa.costs:
        if c.source_key not in costs:
            continue
        newpaid = frappe.utils.flt(c.paid_amount) - frappe.utils.flt(costs[c.source_key])
        c.paid_amount = newpaid if newpaid > 0 else 0
        if c.payment_reference == doc.name:
            c.payment_doctype = None
            c.payment_reference = None
            c.payment_date = None
    for t in wa.transactions:
        if t.name in charges and t.payment_entry == doc.name:
            t.status = "Pending"
            t.payment_entry = None
    wa.save(ignore_permissions=True)

# Payment Entry (After Submit): job cost payments and customer charge receipts
if doc.get("custom_work_allocation") and doc.get("custom_wa_lines"):
    data = json.loads(doc.custom_wa_lines)
    costs = data.get("costs") or {}
    charges = data.get("charges") or []
    wa = frappe.get_doc("Work Allocation", doc.custom_work_allocation)
    for c in wa.costs:
        if c.source_key not in costs:
            continue
        amt = frappe.utils.flt(costs[c.source_key])
        if c.accounting_status != "Posted":
            frappe.throw(f"Cost line '{c.source}' for {c.payee_name} is not posted to accounts yet.")
        newpaid = frappe.utils.flt(c.paid_amount) + amt
        if newpaid > frappe.utils.flt(c.amount) + 0.01:
            frappe.throw(f"This payment would overpay '{c.source}' for {c.payee_name} (amount {c.amount}, already paid {c.paid_amount}).")
        c.paid_amount = newpaid
        c.payment_doctype = "Payment Entry"
        c.payment_reference = doc.name
        c.payment_date = doc.posting_date
    for t in wa.transactions:
        if t.name in charges:
            t.status = "Received"
            t.payment_entry = doc.name
    wa.save(ignore_permissions=True)

# Work Allocation (Job Card) - timeline rows, status, service dates, totals, quotation details.
# Note: plain loops only (comprehensions/closures can't see script locals in the sandbox).

MILESTONES = ["Feasibility Applied", "Feasibility Received", "Allocated", "Work Started", "Work Completed", "KSEB / Authority Inspection", "Registered", "MNRE Process Completed", "Subsidy Received"]
STATUS_ORDER = ["Draft", "Allocated", "Work Started", "Work Completed", "Inspection", "Registered", "MNRE Completed", "Closed"]
MILESTONE_STATUS = {"Allocated": "Allocated", "Work Started": "Work Started", "Work Completed": "Work Completed", "KSEB / Authority Inspection": "Inspection", "Registered": "Registered", "MNRE Process Completed": "MNRE Completed"}
# Milestone that must be dated before a status is allowed (all earlier milestones are then required too)
STATUS_REQUIRES = {"Allocated": "Allocated", "Work Started": "Work Started", "Work Completed": "Work Completed", "Inspection": "KSEB / Authority Inspection", "Registered": "Registered", "MNRE Completed": "MNRE Process Completed", "Closed": "MNRE Process Completed"}

# 1. Timeline: every milestone row exists, in order
existing = {}
current_order = []
for r in doc.milestones:
    existing[r.milestone] = r
    current_order.append(r.milestone)
if current_order != MILESTONES:
    rows = []
    for m in MILESTONES:
        r = existing.get(m)
        if r:
            rows.append({"milestone": m, "date": r.date, "delay_reason": r.delay_reason, "delay_remarks": r.delay_remarks})
        else:
            rows.append({"milestone": m})
    doc.set("milestones", [])
    for row in rows:
        doc.append("milestones", row)

dates = {}
for r in doc.milestones:
    dates[r.milestone] = r.date

# 2a. Timeline must be filled in order, and dates can't go backwards
prev_m = None
prev_d = None
first_missing = None
for m in MILESTONES:
    d = dates.get(m)
    if not d:
        if not first_missing:
            first_missing = m
        continue
    if first_missing:
        frappe.throw(f"Project Timeline: '{m}' has a date but '{first_missing}' does not. Fill the milestones in order.")
    if prev_d and frappe.utils.getdate(d) < frappe.utils.getdate(prev_d):
        frappe.throw(f"Project Timeline: '{m}' ({frappe.utils.formatdate(d)}) cannot be before '{prev_m}' ({frappe.utils.formatdate(prev_d)}).")
    prev_m = m
    prev_d = d

# 2b. Status = furthest milestone reached. A manually chosen status can't be ahead of the timeline.
reached = "Draft"
for m in MILESTONES:
    st = MILESTONE_STATUS.get(m)
    if st and dates.get(m):
        reached = st
cur = doc.status if doc.status in STATUS_ORDER else "Draft"
need = STATUS_REQUIRES.get(cur)
if need and not dates.get(need):
    missing = []
    for m in MILESTONES:
        if not dates.get(m):
            missing.append(m)
        if m == need:
            break
    frappe.throw(
        f"Status cannot be '{cur}' yet. Enter dates in the Project Timeline for: {', '.join(missing)}. "
        f"(Based on the timeline, the current status is '{reached}'.)",
        title="Previous stages not completed",
    )
if cur != "Closed":
    doc.status = reached

# 3. Free services: due dates from Work Completed date (+6 / +12 months)
completed = dates.get("Work Completed")
if completed:
    have = []
    for r in doc.services:
        have.append(r.service_type)
    for st in ["1st Free Service", "2nd Free Service"]:
        if st not in have:
            doc.append("services", {"service_type": st, "service": st, "status": "Pending"})
    if str(doc.service_basis_date or "") != str(completed):
        for r in doc.services:
            if r.status == "Done":
                continue
            if r.service_type == "1st Free Service":
                r.due_date = frappe.utils.add_months(completed, 6)
            elif r.service_type == "2nd Free Service":
                r.due_date = frappe.utils.add_months(completed, 12)
        doc.service_basis_date = completed
    i = 0
    for r in doc.services:
        i += 1
        r.idx = i

# 4. Totals
total_incentive = 0
for r in doc.employees:
    total_incentive += frappe.utils.flt(r.incentive_amount)
collection = 0
payment = 0
for r in doc.transactions:
    if r.transaction_type == "Collection":
        collection += frappe.utils.flt(r.amount)
    elif r.transaction_type == "Payment":
        payment += frappe.utils.flt(r.amount)
expenses = 0
for r in doc.expenses:
    expenses += frappe.utils.flt(r.amount)
doc.total_incentive = total_incentive
doc.total_collection = collection
doc.total_payment = payment
doc.net_balance = collection - payment
doc.total_expenses = expenses

# 5. Project details from the finalised quotation
if doc.quotation:
    q = frappe.get_doc("Quotation", doc.quotation)
    if not doc.customer and q.quotation_to == "Customer":
        doc.customer = q.party_name
    doc.plant_capacity = q.get("custom_total_capacity") or doc.plant_capacity
    doc.roof_type = q.get("custom_roof_type") or doc.roof_type
    panels = []
    inverters = []
    meters = []
    for it in q.items:
        name = (it.item_name or it.item_code or "").lower()
        qty = frappe.utils.flt(it.qty)
        qty_txt = str(int(qty)) if qty == int(qty) else str(qty)
        label = f"{it.item_name} ({qty_txt} {it.uom or 'Nos'})"
        if "inverter" in name:
            inverters.append(label)
        elif "meter" in name:
            meters.append(label)
        elif "panel" in name or "module" in name:
            panels.append(label)
    doc.panel = ", ".join(panels) or doc.panel
    doc.inverter = ", ".join(inverters) or doc.inverter
    doc.net_meter = ", ".join(meters) or doc.net_meter
    if not doc.order_confirmation:
        doc.order_confirmation = frappe.db.get_value("Order Confirmation", {"quotation": doc.quotation}, "name")

# 6. Remarks limit
if doc.remarks and len(doc.remarks) > 500:
    frappe.throw(f"Job Remarks can be at most 500 characters (currently {len(doc.remarks)}).")

# API wa_cost_action: approve / reject / reset job cost lines (approver role)
name = frappe.form_dict.get("name")
action = frappe.form_dict.get("action")
keys = frappe.form_dict.get("keys") or []
if isinstance(keys, str):
    keys = json.loads(keys) if keys else []
if action not in ["approve", "reject", "reset"]:
    frappe.throw("Unknown action")
wa = frappe.get_doc("Work Allocation", name)
wa.check_permission("write")
s = frappe.get_doc("Work Allocation Settings")
roles = frappe.get_all("Has Role", filters={"parent": frappe.session.user, "parenttype": "User"}, pluck="role")
if frappe.session.user == "Administrator":
    roles.append("System Manager")
if not ("System Manager" in roles or (s.approver_role and s.approver_role in roles)):
    frappe.throw(f"Only users with the {s.approver_role or 'approver'} role can approve or reject job costs.")
n = 0
for c in wa.costs:
    if keys and c.source_key not in keys:
        continue
    if c.accounting_status != "Not Posted":
        continue
    if action == "approve" and c.approval_status != "Approved":
        c.approval_status = "Approved"
        c.approved_by = frappe.session.user
        n += 1
    elif action == "reject" and c.approval_status != "Rejected":
        c.approval_status = "Rejected"
        c.approved_by = frappe.session.user
        n += 1
    elif action == "reset" and c.approval_status != "Pending Approval":
        c.approval_status = "Pending Approval"
        c.approved_by = None
        n += 1
if n:
    wa.save()
    wa.add_comment("Comment", f"{n} job cost line(s) {action}d by {frappe.session.user}.")
frappe.response["message"] = {"count": n}

# Work Allocation - Costing (Before Save)
# Builds one cost line per money amount on the Job Card, keeps approval / accounting /
# payment state of existing lines, blocks edits to lines already in accounts, and
# recomputes Job Costing + Accounting Summary.
# Sandbox note: plain loops only (no comprehensions / nested functions).

settings = frappe.get_doc("Work Allocation Settings")
if not doc.company:
    doc.company = settings.company
if not doc.cost_center:
    doc.cost_center = settings.default_cost_center

acct = {}
for r in settings.expense_accounts:
    acct[r.expense_type] = r.expense_account

ATTR_TYPE = {"Lead Generated By": "Lead Referral Commission", "Closed By": "Closing Incentive", "Site Visit By": "Site Visit Incentive", "Other": "Other Sales Incentive"}

# give unsaved child rows a stable name so their cost line key is stable
for tbl in ["attributions", "employees", "expenses", "transactions"]:
    for r in doc.get(tbl):
        if not r.name:
            r.name = frappe.generate_hash(length=10)

wanted = []

for r in doc.attributions:
    amt = frappe.utils.flt(r.amount_payable)
    if amt <= 0:
        continue
    ptype = "Other"
    party = ""
    pname = r.other_person or ""
    if r.person_type == "Employee" and r.employee:
        ptype = "Employee"
        party = r.employee
        pname = frappe.db.get_value("Employee", r.employee, "employee_name") or r.employee
    elif r.person_type == "Referred By" and r.referred_by:
        emp = frappe.db.get_value("Sales Person", r.referred_by, "employee")
        if emp:
            ptype = "Employee"
            party = emp
        pname = r.referred_by
    wanted.append({"source_key": "attributions:" + r.name, "source": r.attribution_type or "Lead / Sales", "cat": "lead", "expense_type": ATTR_TYPE.get(r.attribution_type) or "Other Sales Incentive", "party_type": ptype, "party": party, "payee_name": pname, "amount": amt})

if doc.team_type == "Contractor" and frappe.utils.flt(doc.team_amount) > 0:
    if not doc.team_supplier:
        frappe.throw("Select the Contractor (Supplier) for the team amount.")
    wanted.append({"source_key": "team", "source": "Team / Contractor", "cat": "installation", "expense_type": "Contractor Charges", "party_type": "Supplier", "party": doc.team_supplier, "payee_name": frappe.db.get_value("Supplier", doc.team_supplier, "supplier_name") or doc.team_supplier, "amount": frappe.utils.flt(doc.team_amount)})

for r in doc.employees:
    amt = frappe.utils.flt(r.incentive_amount)
    if amt <= 0:
        continue
    wanted.append({"source_key": "employees:" + r.name, "source": "Work Allocation", "cat": "installation", "expense_type": "Installation Incentive", "party_type": "Employee", "party": r.employee, "payee_name": r.employee_name or frappe.db.get_value("Employee", r.employee, "employee_name") or r.employee, "amount": amt})

if frappe.utils.flt(doc.supervisor_incentive) > 0:
    if not doc.supervised_by:
        frappe.throw("Select the Supervisor for the supervisor incentive.")
    wanted.append({"source_key": "supervisor", "source": "Supervisor", "cat": "supervisor", "expense_type": "Supervisor Incentive", "party_type": "Employee", "party": doc.supervised_by, "payee_name": doc.supervisor_name or frappe.db.get_value("Employee", doc.supervised_by, "employee_name") or doc.supervised_by, "amount": frappe.utils.flt(doc.supervisor_incentive)})

if frappe.utils.flt(doc.travel_amount) > 0 and doc.travel_payable_to:
    if doc.travel_payable_to == "Employee":
        if not doc.travel_employee:
            frappe.throw("Select the Employee the travel expense is payable to.")
        tp = {"party_type": "Employee", "party": doc.travel_employee, "payee_name": frappe.db.get_value("Employee", doc.travel_employee, "employee_name") or doc.travel_employee}
    else:
        tp = {"party_type": "Other", "party": "", "payee_name": doc.travel_person or doc.travel_payable_to}
    line = {"source_key": "travel", "source": "Travel", "cat": "travel", "expense_type": "Travel Expense", "amount": frappe.utils.flt(doc.travel_amount)}
    line.update(tp)
    wanted.append(line)

for r in doc.expenses:
    amt = frappe.utils.flt(r.amount)
    if amt <= 0:
        continue
    ptype = r.party_type or "Other"
    party = ""
    pname = r.payable_to or ""
    if ptype == "Employee":
        party = r.employee
        pname = frappe.db.get_value("Employee", r.employee, "employee_name") or r.employee
    elif ptype == "Supplier":
        party = r.supplier
        pname = frappe.db.get_value("Supplier", r.supplier, "supplier_name") or r.supplier
    label = r.specify_expense if r.expense_type == "Other" and r.specify_expense else r.expense_type
    wanted.append({"source_key": "expenses:" + r.name, "source": "Other Expense: " + (label or ""), "cat": "other", "expense_type": r.expense_type or "Other", "party_type": ptype, "party": party, "payee_name": pname, "amount": amt})

for r in doc.transactions:
    if r.transaction_type != "Payment":
        continue
    amt = frappe.utils.flt(r.amount)
    if amt <= 0:
        continue
    et = r.description if r.description in ["Feasibility Charges", "Registration Charges"] else "Authority Charges"
    label = r.specify_description if r.description == "Other Charges" and r.specify_description else r.description
    wanted.append({"source_key": "transactions:" + r.name, "source": "Charge Paid: " + (label or ""), "cat": "other", "expense_type": et, "party_type": "Other", "party": "", "payee_name": r.paid_to or "KSEB / Authority", "amount": amt})

# merge with existing lines (keep their states)
existing = {}
for c in doc.costs:
    existing[c.source_key] = c

seen = {}
rows = []
for w in wanted:
    seen[w["source_key"]] = 1
    c = existing.get(w["source_key"])
    expense_account = acct.get(w["expense_type"]) or acct.get("Other")
    if not expense_account:
        frappe.throw(f"No expense account mapped for '{w['expense_type']}' in Work Allocation Settings.")
    row = {"source_key": w["source_key"], "source": w["source"], "expense_type": w["expense_type"], "party_type": w["party_type"], "party": w["party"] or "", "payee_name": w["payee_name"] or "", "amount": w["amount"], "expense_account": expense_account, "approval_status": "Pending Approval", "approved_by": None, "accounting_status": "Not Posted", "journal_entry": None, "paid_amount": 0, "payment_doctype": None, "payment_reference": None, "payment_date": None}
    if c:
        changed = abs(frappe.utils.flt(c.amount) - w["amount"]) > 0.005 or (c.party_type or "") != w["party_type"] or (c.party or "") != (w["party"] or "") or (c.expense_type or "") != w["expense_type"]
        if changed and c.accounting_status != "Not Posted":
            frappe.throw(f"'{c.source}' for {c.payee_name} is already in accounts ({c.journal_entry}). Cancel that Journal Entry before changing its amount or payee.")
        row["name"] = c.name
        row["owner"] = c.owner
        row["creation"] = c.creation
        row["approval_status"] = c.approval_status or "Pending Approval"
        row["approved_by"] = c.approved_by
        if changed and row["approval_status"] == "Approved":
            row["approval_status"] = "Pending Approval"
            row["approved_by"] = None
        row["accounting_status"] = c.accounting_status or "Not Posted"
        row["journal_entry"] = c.journal_entry
        row["paid_amount"] = frappe.utils.flt(c.paid_amount)
        row["payment_doctype"] = c.payment_doctype
        row["payment_reference"] = c.payment_reference
        row["payment_date"] = c.payment_date
    row["cat"] = w["cat"]
    rows.append(row)

for c in doc.costs:
    if c.source_key not in seen and c.accounting_status != "Not Posted":
        frappe.throw(f"'{c.source}' for {c.payee_name} is already in accounts ({c.journal_entry}) and can't be removed. Cancel that Journal Entry first.")

# totals
cats = {"lead": 0, "installation": 0, "supervisor": 0, "travel": 0, "other": 0}
total_cost = 0
approved = 0
posted = 0
paid = 0
outstanding = 0
pay_by_party = {"Employee": 0, "Supplier": 0, "Other": 0}
n_pending = 0
n_unposted = 0
doc.set("costs", [])
for row in rows:
    cat = row.pop("cat")
    amt = frappe.utils.flt(row["amount"])
    p = frappe.utils.flt(row["paid_amount"])
    row["outstanding_amount"] = amt - p
    if p <= 0:
        row["payment_status"] = "Unpaid"
    elif p + 0.005 >= amt:
        row["payment_status"] = "Paid"
    else:
        row["payment_status"] = "Partially Paid"
    doc.append("costs", row)
    if row["approval_status"] == "Rejected":
        continue
    cats[cat] = cats[cat] + amt
    total_cost += amt
    paid += p
    if row["approval_status"] == "Pending Approval":
        n_pending += 1
    else:
        approved += amt
        if row["accounting_status"] != "Posted":
            n_unposted += 1
        else:
            posted += amt
            outstanding += amt - p
            pay_by_party[row["party_type"]] = pay_by_party.get(row["party_type"], 0) + amt - p

doc.cost_lead_sales = cats["lead"]
doc.cost_installation = cats["installation"]
doc.cost_supervisor = cats["supervisor"]
doc.cost_travel = cats["travel"]
doc.cost_other = cats["other"]
doc.total_job_cost = total_cost
doc.total_approved = approved
doc.total_posted = posted
doc.total_paid = paid
doc.total_outstanding = approved - paid
doc.employee_payable = pay_by_party["Employee"]
doc.supplier_payable = pay_by_party["Supplier"]
doc.other_payable = pay_by_party["Other"]

if not doc.costs:
    doc.accounting_status = "No Costs"
elif n_pending:
    doc.accounting_status = "Pending Approval"
elif n_unposted:
    doc.accounting_status = "Pending Accounting"
elif paid <= 0:
    doc.accounting_status = "Posted - Unpaid"
elif outstanding > 0.005:
    doc.accounting_status = "Partially Paid"
else:
    doc.accounting_status = "Fully Paid"

# revenue and customer receipts
revenue = 0
grand = 0
if doc.quotation:
    qv = frappe.db.get_value("Quotation", doc.quotation, ["base_net_total", "base_rounded_total", "base_grand_total"], as_dict=True)
    if qv:
        revenue = frappe.utils.flt(qv.base_net_total)
        grand = frappe.utils.flt(qv.base_rounded_total) or frappe.utils.flt(qv.base_grand_total)
doc.job_revenue = revenue
doc.customer_grand_total = grand
doc.gross_contribution = revenue - total_cost
doc.gross_contribution_percent = (revenue - total_cost) * 100.0 / revenue if revenue else 0

received = 0
counted = {}
if doc.customer and not doc.is_new():
    pes = frappe.get_all("Payment Entry", filters={"docstatus": 1, "payment_type": "Receive", "party_type": "Customer", "party": doc.customer, "custom_work_allocation": doc.name}, fields=["name", "base_received_amount"])
    for pe in pes:
        counted[pe.name] = 1
        received += frappe.utils.flt(pe.base_received_amount)
if doc.customer and doc.order_confirmation:
    pes = frappe.get_all("Payment Entry", filters={"docstatus": 1, "payment_type": "Receive", "party_type": "Customer", "party": doc.customer, "custom_order_confirmation": doc.order_confirmation}, fields=["name", "base_received_amount"])
    for pe in pes:
        if pe.name not in counted:
            counted[pe.name] = 1
            received += frappe.utils.flt(pe.base_received_amount)
doc.customer_received = received
doc.customer_outstanding = grand - received
